  public DefaultContext(Request request, Response response, RatpackLaunchConfig launchConfig, ChannelHandlerContext channelHandlerContext, Registry registry, Handler next) {
    this.request = request;
    this.response = response;
    this.launchConfig = launchConfig;
    this.channelHandlerContext = channelHandlerContext;
    this.registry = registry;
    this.next = next;
  }

  public Request getRequest() {
    return request;
  }

  public Response getResponse() {
    return response;
  }

  public <T> T get(Class<T> type) {
    return registry.get(type);
  }

  public <T> T maybeGet(Class<T> type) {
    return registry.maybeGet(type);
  }

  public void next() {
    next.handle(this);
  }

  public void insert(List<Handler> handlers) {
    doNext(this, registry, handlers, 0, next);
